     8	import com.fream.back.domain.user.exception.InvalidPointAmountException;
     9	import com.fream.back.domain.user.exception.UserNotFoundException;
    10	import com.fream.back.domain.user.repository.PointRepository;
    11	import com.fream.back.domain.user.service.query.UserQueryService;
    12	import lombok.RequiredArgsConstructor;
    13	import lombok.extern.slf4j.Slf4j;
    14	import org.springframework.stereotype.Service;
    15	import org.springframework.transaction.annotation.Transactional;
    16	
    17	import java.time.LocalDate;
    18	import java.util.List;
    19	
    20	@Slf4j
    21	@Service
    22	@RequiredArgsConstructor
    23	public class PointCommandService {
    24	
    25	    private final PointRepository pointRepository;
    26	    private final UserQueryService userQueryService;
    27	
    28	    /**
    29	     * 포인트 적립
    30	     */
    31	    @Transactional
    32	    public PointDto.PointResponse addPoint(String email, PointDto.AddPointRequest request) {
    33	        log.info("포인트 적립 시작 - 사용자: {}, 적립액: {}", email, request.getAmount());
    34	
    35	        try {
    36	            // 입력값 검증
    37	            validateAddPointRequest(request);
    38	
    39	            User user = userQueryService.findByEmail(email);
    40	            if (user == null) {
    41	                throw new UserNotFoundException(email);
    42	            }
    43	
    44	            Point point = Point.builder()
    45	                    .user(user)
    46	                    .amount(request.getAmount())
    47	                    .remainingAmount(request.getAmount())
    48	                    .reason(request.getReason())
    49	                    .expirationDate(LocalDate.now().plusDays(90)) // 90일 후 만료
    50	                    .status(PointStatus.AVAILABLE)
    51	                    .build();
    52	
    53	            Point savedPoint = pointRepository.save(point);
    54	
    55	            log.info("포인트 적립 완료 - 사용자: {}, 적립액: {}, 포인트 ID: {}",
    56	                    email, request.getAmount(), savedPoint.getId());
    57	
    58	            return PointDto.PointResponse.from(savedPoint);
    59	        } catch (UserNotFoundException | InvalidPointAmountException e) {
    60	            throw e;
    61	        } catch (Exception e) {
    62	            log.error("포인트 적립 중 예상치 못한 오류 발생 - 사용자: {}, 적립액: {}",
    63	                    email, request.getAmount(), e);
    64	            throw new InvalidPointAmountException("포인트 적립 처리 중 오류가 발생했습니다.");
    65	        }
    66	    }
    67	
    68	    /**
    69	     * 포인트 사용
    70	     */
    71	    @Transactional
    72	    public PointDto.UsePointResponse usePoint(String email, PointDto.UsePointRequest request) {
    73	        log.info("포인트 사용 시작 - 사용자: {}, 사용액: {}", email, request.getAmount());
    74	
    75	        try {
    76	            // 입력값 검증
    77	            validateUsePointRequest(request);
    78	
    79	            User user = userQueryService.findByEmail(email);
    80	            if (user == null) {
    81	                throw new UserNotFoundException(email);
    82	            }
    83	
    84	            int pointsToUse = request.getAmount();
    85	
    86	            // 가용 포인트 총합 확인
    87	            Integer totalAvailable = pointRepository.getTotalAvailablePoints(user);
    88	            if (totalAvailable == null || totalAvailable < pointsToUse) {
    89	                log.warn("포인트 부족 - 사용자: {}, 필요: {}, 보유: {}",
    90	                        email, pointsToUse, totalAvailable != null ? totalAvailable : 0);
    91	                throw new InsufficientPointsException(pointsToUse, totalAvailable != null ? totalAvailable : 0);
    92	            }
    93	
    94	            // 만료 임박 포인트부터 사용
    95	            List<Point> availablePoints = pointRepository.findByUserAndStatusOrderByExpirationDateAsc(user, PointStatus.AVAILABLE);
    96	            int remainingToUse = pointsToUse;
    97	            int totalUsed = 0;
    98	
    99	            for (Point point : availablePoints) {
   100	                if (remainingToUse <= 0) break;
   101	
   102	                Integer usedAmount = point.use(remainingToUse);
   103	                int used = usedAmount != null ? usedAmount : 0;
   104	                remainingToUse -= used;
   105	                totalUsed += used;
   106	
   107	                // 포인트 사용 이유 추가
   108	                if (used > 0) {
   109	                    point.setReason(request.getReason());
   110	                    pointRepository.save(point);
   111	                }
   112	            }
   113	
   114	            // 사용 후 남은 총 포인트 계산
   115	            Integer remainingTotal = pointRepository.getTotalAvailablePoints(user);
   116	            if (remainingTotal == null) remainingTotal = 0;
   117	
   118	            log.info("포인트 사용 완료 - 사용자: {}, 사용액: {}, 남은 포인트: {}",
   119	                    email, totalUsed, remainingTotal);
   120	
   121	            return PointDto.UsePointResponse.builder()
   122	                    .usedPoints(totalUsed)
   123	                    .remainingTotalPoints(remainingTotal)
   124	                    .message("포인트가 성공적으로 사용되었습니다.")
   125	                    .build();
   126	        } catch (UserNotFoundException | InvalidPointAmountException | InsufficientPointsException e) {
   127	            throw e;
   128	        } catch (Exception e) {
   129	            log.error("포인트 사용 중 예상치 못한 오류 발생 - 사용자: {}, 사용액: {}",
   130	                    email, request.getAmount(), e);
   131	            throw new InsufficientPointsException("포인트 사용 처리 중 오류가 발생했습니다.");
   132	        }
   133	    }
   134	
   135	    /**
   136	     * 만료된 포인트 처리 (스케줄러에서 호출)
   137	     */
   138	    @Transactional
   139	    public int expirePoints() {
   140	        log.info("만료 포인트 처리 시작");
   141	
   142	        try {
   143	            List<Point> expiredPoints = pointRepository.findByStatusAndExpirationDateBefore(
   144	                    PointStatus.AVAILABLE, LocalDate.now());
   145	
   146	            for (Point point : expiredPoints) {
   147	                point.expire();
   148	            }
   149	
   150	            log.info("만료 포인트 처리 완료 - 만료된 포인트 수: {}", expiredPoints.size());
   151	            return expiredPoints.size();
   152	        } catch (Exception e) {
   153	            log.error("만료 포인트 처리 중 오류 발생", e);
   154	            return 0;
   155	        }
   156	    }
   157	
   158	    /**
   159	     * 포인트 적립 요청 검증
   160	     */
   161	    private void validateAddPointRequest(PointDto.AddPointRequest request) {
   162	        if (request == null) {
   163	            throw new InvalidPointAmountException("포인트 적립 요청 데이터가 없습니다.");
   164	        }
   165	
   166	        if (request.getAmount() <= 0) {
   167	            throw new InvalidPointAmountException(request.getAmount());
   168	        }
   169	
   170	        if (request.getAmount() > 1000000) { // 최대 100만 포인트 적립 제한
   171	            throw new InvalidPointAmountException("한 번에 적립할 수 있는 포인트는 최대 1,000,000점입니다.");
   172	        }
   173	
   174	        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
   175	            throw new InvalidPointAmountException("포인트 적립 사유를 입력해주세요.");
   176	        }
   177	    }
   178	
   179	    /**
   180	     * 포인트 사용 요청 검증
   181	     */
   182	    private void validateUsePointRequest(PointDto.UsePointRequest request) {
   183	        if (request == null) {
   184	            throw new InvalidPointAmountException("포인트 사용 요청 데이터가 없습니다.");
   185	        }
   186	
   187	        if (request.getAmount() <= 0) {
   188	            throw new InvalidPointAmountException(request.getAmount());
   189	        }
   190	
   191	        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
   192	            throw new InvalidPointAmountException("포인트 사용 사유를 입력해주세요.");
   193	        }
   194	    }
   195	}----
